/* ------------------------------------------------------------------ */
/* Request routing                                                     */
/* ------------------------------------------------------------------ */

static bool read_request(int fd, char *req, size_t cap)
{
	size_t len = 0;

	while (len < cap - 1) {
		ssize_t n = recv(fd, req + len, cap - 1 - len, 0);
		if (n < 0 && errno == EINTR)
			continue;
		if (n <= 0)
			return false;

		len += (size_t)n;
		req[len] = '\0';

		if (strstr(req, "\r\n\r\n"))
			return true;
	}
	return false;   /* headers too large */
}

static void handle_client(int fd, WebGuiContext *ctx)
{
	struct timeval tv = { .tv_sec = 5 };
	setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof tv);
	setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof tv);
	
	char req[4096], method[8], path[256];
	
	if (!read_request(fd, req, sizeof req) ||
	    sscanf(req, "%7s %255s", method, path) != 2) {
		respond_text(fd, 400, "Bad Request");
		return;
	}

	if (strcmp(method, "GET") != 0) {
		respond_text(fd, 405, "Method Not Allowed");
		return;
	}

	if (ctx->auth_enabled && !authorized(req)) {
		respond(fd, 401, "Unauthorized", "text/plain", "Unauthorized", 12,
		        "WWW-Authenticate: Basic realm=\"Lords Mobile Bot\"\r\n");
		return;
	}

	path[strcspn(path, "?")] = '\0';
	
	if (strcmp(path, "/") == 0) {
		respond(fd, 200, "OK", "text/html; charset=utf-8", webgui_page, sizeof webgui_page, "");
	} else if (strcmp(path, "/api/status") == 0) {
		api_status(fd, ctx);
	} else if (strncmp(path, "/api/status/", 12) == 0 && path[12] != '\0' && !strchr(path + 12, '/')) {
		api_bot_status(fd, ctx, path + 12);
	} else {
		respond_text(fd, 404, "Not Found");
	}
}

/* ------------------------------------------------------------------ */
/* Server thread                                                       */
/* ------------------------------------------------------------------ */

static void *server_thread(void *arg)
{
	WebGuiContext *ctx = arg;

	while (!stopping) {
		int fd = accept(listen_fd, NULL, NULL);

		if (fd < 0) {
			if (stopping || errno == EBADF || errno == EINVAL)
				break;
			continue;
		}

		handle_client(fd, ctx);
		close(fd);
	}
	return NULL;
}

int WebGuiStart(WebGuiContext *ctx)
{
	if (!ctx || !ctx->host[0] || !ctx->port || !ctx->client || !ctx->client_count) {
		return 0;
	}
	
	if (ctx->auth_enabled) {
		if (!ctx->password[0]) {
			fprintf(stderr, "Web GUI: auth is enabled but the password is empty\n");
			return 0;
		}

		char creds[200];
		int  n = snprintf(creds, sizeof creds, "%s:%s", ctx->username, ctx->password);

		memcpy(auth_token, "Basic ", 6);
		base64((unsigned char *)creds, (size_t)n, auth_token + 6);
	}

	struct sockaddr_in addr = { .sin_family = AF_INET, .sin_port = htons(ctx->port) };
	if (inet_pton(AF_INET, ctx->host, &addr.sin_addr) != 1) {
		fprintf(stderr, "Web GUI: invalid host '%s'\n", ctx->host);
		return 0;
	}

	listen_fd = socket(AF_INET, SOCK_STREAM, 0);
	if (listen_fd < 0) {
		perror("Web GUI socket");
		return 0;
	}

	int one = 1;
	setsockopt(listen_fd, SOL_SOCKET, SO_REUSEADDR, &one, sizeof one);

	if (bind(listen_fd, (struct sockaddr *)&addr, sizeof addr) < 0 ||
	    listen(listen_fd, 8) < 0) {
		perror("Web GUI bind/listen");
		goto fail;
	}

	stopping = 0;
	if (pthread_create(&thread, NULL, server_thread, ctx) != 0)
		goto fail;

	started = true;
	printf("Web GUI listening on http://%s:%u/\n", ctx->host, (unsigned)ctx->port);
	return 1;

fail:
	close(listen_fd);
	listen_fd = -1;
	return 0;
}

void WebGuiStop(void)
{
	if (!started)
		return;

	stopping = 1;
	shutdown(listen_fd, SHUT_RDWR);   /* wakes the thread out of accept() */
	pthread_join(thread, NULL);

	close(listen_fd);
	listen_fd = -1;
	started = false;
}
